mapper.select:
SELECT  FROM rpl_policy_version
      WHERE tenant_id=#{tenantId} AND store_id=#{storeId} AND state=#{state}
      ORDER BY version_no DESC LIMIT #{limit}

mapper.update:
UPDATE rpl_policy_version SET state=#{nextState},content_sha256=#{contentSha256},
      version=version+1,updated_at=#{at} WHERE tenant_id=#{tenantId} AND policy_version_id=#{policyVersionId}
      AND state=#{expectedState} AND version=#{expectedVersion}

UPDATE rpl_generation_run SET state='COMPLETED',suggestion_count=#{suggestionCount},
      version=version+1,updated_at=#{at} WHERE tenant_id=#{tenantId} AND generation_run_id=#{generationRunId}
      AND state='RUNNING' AND version=#{expectedVersion}

mapper.select:
SELECT  FROM rpl_suggestion
      WHERE tenant_id=#{tenantId} AND store_id=#{storeId} AND state=#{state}
      ORDER BY created_at DESC,suggestion_id LIMIT #{limit}

SELECT 
      FROM rpl_suggestion WHERE tenant_id=#{tenantId} AND warehouse_id=#{warehouseId} AND sku_id=#{skuId}
      AND state IN ('GENERATED','REVIEWED','APPROVED') ORDER BY created_at FOR UPDATE

mapper.update:
UPDATE rpl_suggestion SET state=#{nextState},purchase_order_id=#{purchaseOrderId},
      failure_code=#{failureCode},reviewer_user_id=COALESCE(#{reviewerUserId},reviewer_user_id),
      approver_user_id=COALESCE(#{approverUserId},approver_user_id),version=version+1,updated_at=#{at}
      WHERE tenant_id=#{tenantId} AND suggestion_id=#{suggestionId} AND state=#{expectedState} AND version=#{expectedVersion}

mapper.select:
SELECT idempotency_key AS idempotencyKey,command_sha256 AS commandSha256,suggestion_id AS aggregateId,
  result_state AS resultState,result_reference_id AS resultReferenceId FROM rpl_suggestion_event
WHERE tenant_id=#{tenantId} AND idempotency_key=#{idempotencyKey}

SELECT command_id AS idempotencyKey,request_sha256 AS commandSha256,aggregate_id AS aggregateId,
  after_value AS resultState,CAST(NULL AS CHAR(26)) AS resultReferenceId FROM rpl_audit_event
WHERE tenant_id=#{tenantId} AND command_id=#{idempotencyKey}
